import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() - days);
  return base;
};

const presets = [
  { id: 'today', label: 'Сегодня', days: 0 },
  { id: 'yesterday', label: 'Вчера', days: 1 },
  { id: 'week-ago', label: 'Неделя назад', days: 7 },
];

const isSameDay = (a: Date | null, b: Date | null) =>
  a !== null &&
  b !== null &&
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(null);
  const selected = value !== undefined ? value : internalDate;

  const selectDate = (next: Date | null) => {
    if (value === undefined) {
      setInternalDate(next);
    }
    onChange?.(next);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '12px',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => (
          <JxChip
            key={preset.id}
            active={isSameDay(selected, shiftDays(preset.days))}
            onClick={() => selectDate(shiftDays(preset.days))}
          >
            {preset.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar
        locale="ru-RU"
        value={selected}
        onValueChange={(next) => selectDate(next === null ? null : startOfDay(next))}
      />
    </div>
  );
}

